// Monta os e-mails da demanda recebida: uma saída por e-mail (o nó seguinte envia cada um pelo Resend).
// Para mudar textos/assuntos, edite só este nó. Etapas: "retorno" (cliente não respondeu) e
// "assinatura" (um e-mail por signatário que ainda não assinou). `aviso` = e-mail interno (comercial ou jurídico).
const i = $('Webhook').first().json.body;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (d) => (d?.nome ? `${d.nome} <${d.email}>` : d?.email);
const primeiro = (n) => (n ? String(n).split(' ')[0] : '');
const tipo = i.tipoDocumentoLabel || 'Documento';
const empresa = i.empresa?.nome || '';
const dias = i.diasAguardando == null ? '' : `${i.diasAguardando} dia${i.diasAguardando === 1 ? '' : 's'}`;
const from = i.remetente || 'BMS Consultoria Tributária <no-reply@bmsprojetos.com>';

const botao = (url, texto) => url ? `<tr><td style="padding:4px 32px 8px 32px;text-align:center;">
  <a href="${esc(url)}" style="display:inline-block;background:#E8620E;color:#ffffff;text-decoration:none;padding:14px 28px;border-radius:8px;font-size:14px;font-weight:700;">${esc(texto)}</a></td></tr>` : '';
const layout = ({ rotulo, titulo, corpo, cta = '', rodape = 'Este é um e-mail automático.' }) => `<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /></head>
<body style="margin:0;padding:0;background:#F3F5F8;font-family:Arial,Helvetica,sans-serif;color:#0F2A47;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#F3F5F8;padding:32px 12px;"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #E3E8EF;border-radius:10px;overflow:hidden;">
  <tr><td style="background:#0F2A47;padding:24px 32px;">
    <div style="color:#ffffff;font-size:22px;font-weight:700;letter-spacing:0.06em;">BMS</div>
    <div style="margin-top:2px;color:#F2A46B;font-size:10px;letter-spacing:0.28em;text-transform:uppercase;">Consultoria Tributária</div>
  </td></tr>
  <tr><td style="height:3px;background:#E8620E;"></td></tr>
  <tr><td style="padding:32px 32px 8px 32px;">
    <p style="margin:0 0 8px 0;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:#6B7A8D;">${esc(rotulo)}</p>
    <h1 style="margin:0 0 16px 0;font-size:22px;line-height:1.3;color:#0F2A47;">${esc(titulo)}</h1>
    ${corpo}
  </td></tr>
  ${cta}
  <tr><td style="padding:28px 32px 0 32px;"><div style="border-top:1px solid #E3E8EF;"></div></td></tr>
  <tr><td style="padding:16px 32px 24px 32px;text-align:center;">
    <p style="margin:0 0 4px 0;font-size:12px;color:#0F2A47;font-weight:700;">BMS Consultoria Tributária</p>
    <p style="margin:0;font-size:11px;color:#8A9AAC;">${esc(rodape)}</p>
  </td></tr>
</table></td></tr></table></body></html>`;
const p = (t) => `<p style="margin:0 0 12px 0;font-size:14px;line-height:1.6;">${t}</p>`;
const contatoComercial = i.comercial?.nome
  ? p(`<span style="font-size:13px;color:#3A4A5E;">Dúvidas? Fale com <strong>${esc(i.comercial.nome)}</strong> (<a href="mailto:${esc(i.comercial.email)}" style="color:#E8620E;">${esc(i.comercial.email)}</a>).</span>`)
  : '';

const emails = [];

if (i.etapa === 'retorno') {
  const saud = primeiro(i.para?.[0]?.nome) ? `Olá, ${esc(primeiro(i.para[0].nome))},` : 'Olá,';
  emails.push({
    tipo: 'cliente',
    from, to: i.para.map(fmt), cc: (i.cc || []).map(fmt),
    subject: `Lembrete: ${tipo} — ${empresa} aguarda sua revisão`,
    html: layout({
      rotulo: `${tipo} · lembrete`,
      titulo: empresa,
      corpo: p(saud)
        + p(`Há ${esc(dias || 'alguns dias')} enviamos o <strong>${esc(tipo.toLowerCase())}</strong> para sua revisão e ainda não recebemos retorno.`)
        + p('Pelo portal você pode ler, comentar trechos, enviar sua versão ou aprovar o documento — leva poucos minutos.')
        + contatoComercial,
      cta: botao(i.links?.portal, 'Revisar documento no portal'),
      rodape: 'Este é um lembrete automático. O link do portal é pessoal e expira em alguns dias.',
    }),
  });
} else {
  for (const s of i.pendentes.length ? i.pendentes : i.para.map((d) => ({ ...d, link: null }))) {
    const jaAssinaram = (i.assinaram || []).length
      ? p(`<span style="font-size:13px;color:#3A4A5E;">Já assinaram: ${esc(i.assinaram.join(', '))}.</span>`) : '';
    emails.push({
      tipo: 'cliente',
      from, to: [fmt(s)], cc: [],
      subject: `Lembrete: assinatura pendente — ${tipo} ${empresa}`,
      html: layout({
        rotulo: `${tipo} · assinatura pendente`,
        titulo: empresa,
        corpo: p(primeiro(s.nome) ? `Olá, ${esc(primeiro(s.nome))},` : 'Olá,')
          + p(`O documento <strong>${esc(i.titulo)}</strong> está aguardando a sua assinatura${dias ? ` há ${esc(dias)}` : ''}.`)
          + (s.link ? p('É só clicar no botão abaixo — a assinatura é digital e leva menos de 2 minutos.')
                    : p('Procure o e-mail da plataforma de assinatura na sua caixa de entrada (verifique também o spam) para concluir.'))
          + jaAssinaram + (s.lado === 'bms' ? '' : contatoComercial),
        cta: botao(s.link, 'Assinar documento'),
        rodape: 'Este é um lembrete automático. Se você já assinou, desconsidere esta mensagem.',
      }),
    });
  }
}

if (i.aviso && i.aviso.para?.length) {
  const paraJuridico = i.aviso.destino === 'juridico';
  const cobrados = i.etapa === 'retorno' ? i.para : (i.pendentes.length ? i.pendentes : i.para);
  const lista = cobrados.map((d) => `<li>${esc(d.nome || d.email)}${d.nome ? ` — ${esc(d.email)}` : ''}${d.lado ? ` (${d.lado === 'bms' ? 'BMS' : 'cliente'}${d.papel === 'testemunha' ? ', testemunha' : ''})` : ''}</li>`).join('');
  emails.push({
    tipo: 'aviso',
    from, to: i.aviso.para.map(fmt), cc: (i.aviso.cc || []).map(fmt),
    subject: `[Ação necessária] ${empresa} — ${i.etapa === 'retorno' ? `${tipo} sem retorno do cliente` : `assinatura pendente (${tipo})`}`,
    html: layout({
      rotulo: paraJuridico ? 'Aviso ao jurídico' : 'Aviso ao comercial',
      titulo: `${empresa}${i.oportunidade ? ` · ${i.oportunidade}` : ''}`,
      corpo: p(primeiro(i.aviso.para[0]?.nome) ? `Olá, ${esc(primeiro(i.aviso.para[0].nome))},` : 'Olá,')
        + p(esc(i.aviso.motivo))
        + p(`<strong>${i.etapa === 'retorno' ? 'Contatos cobrados' : 'Ainda não assinaram'}:</strong>`)
        + `<ul style="margin:0 0 12px 0;padding-left:20px;font-size:14px;line-height:1.6;">${lista}</ul>`
        + p(paraJuridico
          ? 'Falta só a assinatura do lado da BMS. Peça para o(s) assinante(s) concluírem pelo link que receberam do Assinafy.'
          : i.etapa === 'retorno'
            ? 'As cobranças por e-mail não tiveram resposta. Sugerimos um contato direto (telefone ou WhatsApp) para entender se há dúvidas ou ajustes no documento. Os lembretes automáticos continuam.'
            : 'Os lembretes por e-mail não foram suficientes. Sugerimos um contato direto com o cliente para concluir a assinatura. Os lembretes automáticos continuam.'),
      cta: botao(i.links?.juridico, 'Abrir a demanda no sistema'),
      rodape: 'Aviso automático do follow-up de contratos. Enviado uma vez por etapa.',
    }),
  });
}

return emails.map((e) => ({ json: e }));

// Junta o resultado dos envios (um item por e-mail, na mesma ordem do "Monta e-mails") e prepara o retorno ao sistema.
// Falha no e-mail ao cliente → resultado "erro" (o sistema tenta de novo em 1h). Falha só no aviso interno →
// a cobrança conta, mas o aviso fica para a próxima rodada.
const i = $('Webhook').first().json.body;
const emails = $('Monta e-mails').all().map((x) => x.json);
const respostas = $input.all().map((x) => x.json);

const resendIds = [];
const erros = [];
let comercialAvisado = false;
emails.forEach((e, n) => {
  const r = respostas[n] || {};
  const ok = !r.error && r.id;
  if (e.tipo === 'aviso') comercialAvisado = !!ok;
  else if (ok) resendIds.push(r.id);
  else erros.push(`${e.to.join(', ')}: ${r.error?.message || r.error || 'sem resposta do Resend'}`);
});

return [{ json: {
  acao: 'registrar',
  documentoId: i.documentoId,
  etapa: i.etapa,
  numero: i.numero,
  resultado: resendIds.length ? 'enviado' : 'erro',
  erro: erros.join('; ') || null,
  para: emails.filter((e) => e.tipo !== 'aviso').flatMap((e) => e.to),
  resendIds,
  comercialAvisado,
  avisoDestino: i.aviso?.destino ?? null,
} }];

